export namespace Effect {
  export interface Effect<A, E = never, R = never> {
    readonly _A?: A;
    readonly _E?: E;
    readonly _R?: R;
  }

  export function runPromise<A, E, R>(effect: Effect<A, E, R>): Promise<A>;
  export function sync<A>(evaluate: () => A): Effect<A>;
  export function tryPromise<A>(
    evaluate:
      | (() => Promise<A>)
      | {
          readonly try: () => Promise<A>;
          readonly catch?: (error: unknown) => unknown;
        }
  ): Effect<A>;
  export function succeed<A>(value: A): Effect<A>;
}

export namespace Layer {
  export interface Layer<ROut, E = never, RIn = never> {
    readonly _ROut?: ROut;
    readonly _E?: E;
    readonly _RIn?: RIn;
  }

  export function succeed<Id, Value>(tag: Context.Tag<Id, Value>, value: Value): Layer<Id>;
}

export namespace Context {
  export interface Tag<Id, Value> extends Effect.Effect<Value, never, Id> {}

  export function GenericTag<Id, Value>(id: string): Tag<Id, Value>;
}
